"""Static lesson pages and reproducible simulated reports for published physics labs."""
from pathlib import Path
import json,math,csv,io,sqlite3,html
ROOT=Path(__file__).resolve().parent;G=9.80665;PI=math.pi
E=lambda s:html.escape(str(s),quote=True)
def specs():return json.loads((ROOT/'content/physics/experiments.json').read_text())
def rnd(x,n):return math.floor(x*10**n+.5)/10**n

def observation(c,value):
 slug=c['slug']
 if slug=='simple-pendulum':
  theta=3*PI/180;T=2*PI*math.sqrt(value/G)*(1+theta**2/16+11*theta**4/3072);raw=rnd(20*T,2);x=value;y=(raw/20)**2
 elif slug=='bifilar-suspension':
  I=.5*.5**2/12;T=2*PI*math.sqrt(I*value/(.5*G*.1**2));raw=rnd(20*T,2);x=value;y=(raw/20)**2
 elif slug=='young-modulus':x=value;raw=rnd(value*2/(PI*.0005**2/4*200e9)*1000,3);y=raw/1000
 elif slug=='stokes-viscosity':x=(value/1000)**2;speed=2*1240*G*x/(9*1.2);raw=rnd(.1/speed,2);y=.1/raw
 elif slug=='ohms-law':x=value;raw=rnd(value/100*1000,2);y=raw/1000
 elif slug=='metre-bridge':x=value;raw=rnd(100*5/(5+value),1);y=(100-raw)/raw
 elif slug=='rc-charging':x=value;raw=rnd(5*(1-math.exp(-value)),3);y=math.log(5/(5-raw))
 elif slug=='glass-slab':x=value/1000;raw=rnd(value/1.5,2);y=raw/1000
 elif slug=='diffraction-grating':x=value;raw=rnd(math.asin(value*550e-9/(1e-3/300))*180/PI,2);y=math.sin(raw*PI/180)
 elif slug=='hookes-law':x=value;raw=rnd(value/25.0*1000,1);y=raw/1000
 elif slug=='density-measurement':x=value*1e-6;raw=rnd(value*8.96,2);y=raw/1000
 elif slug=='vernier-micrometer':x=value/1000;raw=rnd(value*PI,2);y=raw/1000
 elif slug=='friction-laws':x=value;raw=rnd(value*0.35,2);y=raw
 elif slug=='principle-of-moments':m_kg=value/1000.0;raw=rnd((0.018/m_kg)*100,1);x=1.0/m_kg;y=raw/100.0
 elif slug=='force-table':rad=value*PI/180;x=math.cos(rad);raw=rnd(2*150.0*x,1);y=raw/1000.0
 elif slug=='equilibrium-forces':d_AB=0.80;x_A=0.10;W_bar=2.00;W_load=5.00;ideal=(W_bar*0.40/d_AB)+(W_load/d_AB)*(value-x_A);raw=rnd(ideal,2);x=value;y=raw
 elif slug=='free-fall':ideal=math.sqrt(2*value/G);raw=rnd(ideal,4);x=raw*raw;y=value
 elif slug=='newtons-second-law':ideal=value/1.200;raw=rnd(ideal,3);x=value;y=raw
 elif slug=='ballistic-pendulum':p0=0.250;M=(value+50.0)/1000.0;V=p0/M;h_ideal=(V*V/(2*G))*100.0;raw=rnd(h_ideal,2);x=1.0/M;y=math.sqrt(2*G*(raw/100.0))
 elif slug=='conical-pendulum':rad=math.radians(value);h=1.000*math.cos(rad);T=2*math.pi*math.sqrt(h/G);raw=rnd(20*T,2);x=h;y=(raw/20.0)**2
 elif slug=='flywheel-inertia':ideal=value/0.050;raw=rnd(ideal,3);x=value;y=raw
 elif slug=='specific-heat-capacity':m_kg=value/1000.0;Csys=920.92;Ts=100.0;T0=20.0;cs=385.0;ideal=(m_kg*cs*Ts+Csys*T0)/(m_kg*cs+Csys);raw=rnd(ideal,2);x=m_kg*(Ts-raw);y=Csys*(raw-T0)
 elif slug=='newtons-cooling':T0=20.0;theta0=60.0;k=0.0960;ideal=T0+theta0*math.exp(-k*value);raw=rnd(ideal,2);theta=raw-T0;x=value;y=math.log(theta0/theta)
 elif slug=='solidification-cooling':Lf=79500;R_loss=270.0;m_kg=value/1000.0;ideal=(m_kg*Lf)/R_loss;raw=rnd(ideal,2);x=m_kg;y=raw*R_loss
 elif slug=='latent-heat-vaporization':cw=4186.0;Csys=866.08;Ts=100.0;T0=15.0;Lv=2260000.0;m_kg=value/1000.0;ideal=(m_kg*Lv+m_kg*cw*Ts+Csys*T0)/(Csys+m_kg*cw);raw=rnd(ideal,2);x=m_kg;y=Csys*(raw-T0)-m_kg*cw*(Ts-raw)
 elif slug=='latent-heat-fusion':cw=4186.0;Csys=866.08;T0=30.0;Lf=334000.0;m_kg=value/1000.0;ideal=(Csys*T0-m_kg*Lf)/(Csys+m_kg*cw);raw=rnd(ideal,2);x=m_kg;y=Csys*(T0-raw)-m_kg*cw*raw
 elif slug=='thermal-expansion':L0=1.000;alpha=16.80e-6;ideal=L0*alpha*value*1000.0;raw=rnd(ideal,3);x=L0*value;y=raw/1000.0
 elif slug=='mechanical-equivalent-heat':r=0.050;M=3.00;g=9.80665;W1=2*math.pi*r*M*g;Csys_cal=118.48;J_ref=4.1860;T0=20.00;W=value*W1;Q_cal=W/J_ref;dT=Q_cal/Csys_cal;ideal=T0+dT;raw=rnd(ideal,2);dT_obs=raw-T0;x=Csys_cal*dT_obs;y=W
 elif slug=='boyles-law':k_ref=3.03975;V_m3=value*1e-6;P_Pa=k_ref/V_m3;raw=rnd(P_Pa/1000.0,2);x=1.0/V_m3;y=raw*1000.0
 elif slug=='charles-law-volume':V0_cm3=100.00;beta_ref=1.0/273.15;ideal=V0_cm3*(1.0+beta_ref*value);raw=rnd(ideal,2);x=value;y=raw*1e-6
 else:x=100/value;raw=rnd(100/(1/.15-100/value),1);y=100/raw
 return {'input':value,'raw':raw,'x':x,'y':y,'angle':3}

def fit(rows):
 n=len(rows);mx=sum(r['x'] for r in rows)/n;my=sum(r['y'] for r in rows)/n;sxx=sum((r['x']-mx)**2 for r in rows);sxy=sum((r['x']-mx)*(r['y']-my) for r in rows);m=sxy/sxx;b=my-m*mx;sse=sum((r['y']-m*r['x']-b)**2 for r in rows);variance=sse/(n-2)
 return dict(m=m,b=b,sse=sse,slopeSE=math.sqrt(variance/sxx),interceptSE=math.sqrt(variance*(1/n+mx*mx/sxx)),mx=mx,my=my,sxx=sxx,sxy=sxy)

def estimate(c,f):
 s=c['slug']
 if s in ['ohms-law','metre-bridge','rc-charging','glass-slab','hookes-law']:return 1/f['m'],f['slopeSE']/f['m']**2,{'ohms-law':100,'metre-bridge':5,'rc-charging':1,'glass-slab':1.5,'hookes-law':25.0}[s]
 if s=='density-measurement':return f['m'],f['slopeSE'],8960.0
 if s=='vernier-micrometer':return f['m'],f['slopeSE'],PI
 if s=='friction-laws':return f['m'],f['slopeSE'],0.35
 if s=='principle-of-moments':return f['m']/0.150,f['slopeSE']/0.150,0.120
 if s=='force-table':return f['m']/2.0,f['slopeSE']/2.0,0.150
 if s=='equilibrium-forces':return f['m']*0.80,f['slopeSE']*0.80,5.00
 if s=='free-fall':return 2.0*f['m'],2.0*f['slopeSE'],9.80665
 if s=='newtons-second-law':return 1.0/f['m'],f['slopeSE']/(f['m']**2),1.200
 if s=='ballistic-pendulum':return f['m']/0.050,f['slopeSE']/0.050,5.000
 if s=='conical-pendulum':return (4*math.pi**2)/f['m'],(4*math.pi**2)*f['slopeSE']/(f['m']**2),9.80665
 if s=='flywheel-inertia':return 1.0/f['m'],f['slopeSE']/(f['m']**2),0.050
 if s=='specific-heat-capacity':return f['m'],f['slopeSE'],385.0
 if s=='newtons-cooling':return f['m'],f['slopeSE'],0.0960
 if s=='solidification-cooling':return f['m'],f['slopeSE'],79500.0
 if s=='latent-heat-vaporization':return f['m'],f['slopeSE'],2260000.0
 if s=='latent-heat-fusion':return f['m'],f['slopeSE'],334000.0
 if s=='thermal-expansion':return f['m'],f['slopeSE'],16.80e-6
 if s=='mechanical-equivalent-heat':return f['m'],f['slopeSE'],4.1860
 if s=='boyles-law':return f['m'],f['slopeSE'],3.03975
 if s=='charles-law-volume':return f['m']/1e-4,f['slopeSE']/1e-4,1.0/273.15
 if s=='diffraction-grating':return f['m']*(1e-3/300),f['slopeSE']*(1e-3/300),550e-9
 if s=='convex-lens':return 1/f['b'],f['interceptSE']/f['b']**2,.15
 if s=='bifilar-suspension':const=.5*G*.1**2/(4*PI**2);return const*f['m'],const*f['slopeSE'],.5*.5**2/12
 const=4*PI**2 if s=='simple-pendulum' else 2/(PI*.0005**2/4) if s=='young-modulus' else 2*1240*G/9
 return const/f['m'],const*f['slopeSE']/f['m']**2,G if s=='simple-pendulum' else 200e9 if s=='young-modulus' else 1.2

def fmt(v,n=5):return f'{v:.4e}' if v and (abs(v)<.001 or abs(v)>=1e6) else f'{v:.{n}f}'
def formula(c,f):
 if c['slug'] in ['ohms-law','metre-bridge','rc-charging','glass-slab','hookes-law']:
  value=estimate(c,f)[0]*c['resultScale']
  return f'{c["target"]} = 1/m = 1/({fmt(f["m"],8)}) = {fmt(value,6)} {c["resultUnit"]}'
 if c['slug']=='density-measurement':return f'ρ = m = {fmt(f["m"],6)} kg m⁻³'
 if c['slug']=='vernier-micrometer':return f'π = m = {fmt(f["m"],6)}'
 if c['slug']=='friction-laws':return f'μ = m = {fmt(f["m"],6)}'
 if c['slug']=='principle-of-moments':return f'Slope S = {fmt(f["m"],6)} m kg; M_rule = S / d_rule = {fmt(f["m"],6)} / 0.150 m = {fmt(estimate(c,f)[0],5)} kg ({fmt(estimate(c,f)[0]*1000,2)} g)'
 if c['slug']=='force-table':return f'Slope S = {fmt(f["m"],6)} kg; M₀ = S / 2 = {fmt(f["m"],6)} / 2 = {fmt(estimate(c,f)[0],5)} kg ({fmt(estimate(c,f)[0]*1000,2)} g)'
 if c['slug']=='equilibrium-forces':return f'Slope S = {fmt(f["m"],6)} N m⁻¹; W_load = S × d_AB = {fmt(f["m"],6)} × 0.800 m = {fmt(estimate(c,f)[0],4)} N'
 if c['slug']=='free-fall':return f'Slope S = {fmt(f["m"],6)} m s⁻²; g = 2 × S = 2 × {fmt(f["m"],6)} = {fmt(estimate(c,f)[0],4)} m s⁻²'
 if c['slug']=='newtons-second-law':return f'Slope S = {fmt(f["m"],6)} kg⁻¹; Total mass M_total = 1 / S = 1 / {fmt(f["m"],6)} = {fmt(estimate(c,f)[0],4)} kg'
 if c['slug']=='ballistic-pendulum':return f'Slope S = {fmt(f["m"],6)} kg m s⁻¹; Muzzle velocity v₀ = S / m_b = {fmt(f["m"],6)} / 0.0500 kg = {fmt(estimate(c,f)[0],4)} m s⁻¹'
 if c['slug']=='conical-pendulum':return f'Slope S = {fmt(f["m"],6)} s² m⁻¹; g = 4π² / S = 4π² / {fmt(f["m"],6)} = {fmt(estimate(c,f)[0],4)} m s⁻²'
 if c['slug']=='flywheel-inertia':return f'Slope S = {fmt(f["m"],6)} kg⁻¹ m⁻²; Moment of inertia I = 1 / S = 1 / {fmt(f["m"],6)} = {fmt(estimate(c,f)[0],4)} kg m²'
 if c['slug']=='specific-heat-capacity':return f'Slope S = {fmt(f["m"],6)} J kg⁻¹ K⁻¹; Specific heat c_s = S = {fmt(estimate(c,f)[0],4)} J kg⁻¹ K⁻¹'
 if c['slug']=='newtons-cooling':return f'Slope S = {fmt(f["m"],6)} min⁻¹; Cooling constant k = S = {fmt(estimate(c,f)[0],4)} min⁻¹'
 if c['slug']=='solidification-cooling':return f'Slope S = {fmt(f["m"],4)} J kg⁻¹; Latent heat of fusion L_f = S × 0.001 = {fmt(estimate(c,f)[0]*0.001,2)} kJ kg⁻¹'
 if c['slug']=='latent-heat-vaporization':return f'Slope S = {fmt(f["m"],2)} J kg⁻¹; Latent heat of vaporization L_v = S × 0.001 = {fmt(estimate(c,f)[0]*0.001,2)} kJ kg⁻¹'
 if c['slug']=='latent-heat-fusion':return f'Slope S = {fmt(f["m"],2)} J kg⁻¹; Latent heat of fusion L_f = S × 0.001 = {fmt(estimate(c,f)[0]*0.001,2)} kJ kg⁻¹'
 if c['slug']=='thermal-expansion':return f'Slope S = {fmt(f["m"],8)} K⁻¹; Linear expansion coefficient α = S × 10⁶ = {fmt(estimate(c,f)[0]*1e6,2)} × 10⁻⁶ K⁻¹'
 if c['slug']=='mechanical-equivalent-heat':return f'Slope S = {fmt(f["m"],4)} J cal⁻¹; Mechanical equivalent of heat J = S = {fmt(estimate(c,f)[0],3)} J cal⁻¹'
 if c['slug']=='boyles-law':return f'Slope S = {fmt(f["m"],5)} J; Isothermal state constant k = PV = S = {fmt(estimate(c,f)[0],3)} J'
 if c['slug']=='charles-law-volume':return f'Slope S = {fmt(f["m"],8)} m³ K⁻¹; V₀ = 1.000 × 10⁻⁴ m³; β = S / V₀ = {fmt(estimate(c,f)[0],6)} K⁻¹; Extrapolated T₀ = -b / S = {fmt(-f["b"]/f["m"],2)} °C'
 if c['slug']=='diffraction-grating':return f'd = (10⁻³ m)/300 = {fmt(1e-3/300)} m; λ = md = {fmt(f["m"],8)} × d = {estimate(c,f)[0]*1e9:.4f} nm'
 if c['slug']=='simple-pendulum':return f'g = 4π² / {fmt(f["m"],8)} = {fmt(4*PI**2/f["m"],6)} m s⁻²'
 if c['slug']=='bifilar-suspension':return f'I = ({fmt(f["m"],8)} × 0.500 × 9.80665 × 0.100²) / (4π²) = {fmt(estimate(c,f)[0],8)} kg m²'
 if c['slug']=='young-modulus':return f'A = π(0.000500)²/4 = {fmt(PI*.0005**2/4)} m²; Y = 2.000 / (A × {fmt(f["m"])}) = {fmt(estimate(c,f)[0])} Pa'
 if c['slug']=='stokes-viscosity':return f'η = [2 × (2500 − 1260) × 9.80665] / [9 × {fmt(f["m"],4)}] = {fmt(estimate(c,f)[0],6)} Pa s'
 return f'f = 1 / {fmt(f["b"],8)} = {fmt(estimate(c,f)[0],6)} m = {estimate(c,f)[0]*100:.4f} cm'

def worked(c,r):
 s=c['slug'];i=r['input'];raw=r['raw']
 if s in ['simple-pendulum','bifilar-suspension']:return f'L = {i:.2f} m; t₂₀ = {raw:.2f} s; T = t₂₀/20 = {raw/20:.4f} s; T² = {r["y"]:.6f} s².'
 if s=='young-modulus':return f'F = {i:.1f} N; δ = {raw:.3f} mm = {fmt(r["y"])} m. Area A = πd²/4 = {fmt(PI*.0005**2/4)} m². Single-reading Y = FL₀/(Aδ) = {i*2/(PI*.0005**2/4*r["y"])/1e9:.3f} GPa; use all readings in the fit for the reported estimate.'
 if s=='stokes-viscosity':return f'r = {i:.2f} mm = {fmt(i/1000)} m; r² = {fmt(r["x"])} m². For gate distance 0.100 m and time {raw:.2f} s, v = s/t = {fmt(r["y"])} m s⁻¹.'
 if s=='ohms-law':return f'V = {i:.1f} V; I = {raw:.2f} mA = {raw/1000:.5f} A; single-reading R = V/I = {i/(raw/1000):.3f} Ω. Fit I against V, using amperes.'
 if s=='metre-bridge':return f'S = {i:.1f} Ω; l = {raw:.1f} cm; other segment = {100-raw:.1f} cm; y = (100 − l)/l = {r["y"]:.6f}. R = Sl/(100 − l) = {i*raw/(100-raw):.4f} Ω.'
 if s=='rc-charging':return f't = {i:.1f} s; Vc = {raw:.3f} V; E − Vc = {5-raw:.3f} V; y = ln[5/(5 − {raw:.3f})] = {r["y"]:.6f}. The logarithm is dimensionless.'
 if s=='glass-slab':return f'R₁ = 0.00 mm; R₂ = {i:.2f} mm; R₃ = {i-raw:.2f} mm. Real depth t = R₂ − R₁ = {i:.2f} mm; apparent depth a = R₂ − R₃ = {raw:.2f} mm. Thus n = t/a = {i/raw:.5f}.'
 if s=='diffraction-grating':return f'Order k = {i:.0f}; left/right angles relative to the central maximum = −{raw:.2f}° and +{raw:.2f}°; θ = half their separation = {raw:.2f}°. y = sin(θ) = {r["y"]:.6f}; single-order λ = d sin(θ)/k = {(1e-3/300)*r["y"]/i*1e9:.3f} nm.'
 if s=='hookes-law':return f'F = {i:.2f} N; observed extension δ = {raw:.1f} mm = {fmt(r["y"])} m. Single-reading k = F/δ = {i/r["y"]:.2f} N m⁻¹. Linear regression over all loads yields the reported spring stiffness constant.'
 if s=='density-measurement':return f'V = {i:.1f} cm³ = {fmt(r["x"])} m³; M = {raw:.2f} g = {fmt(r["y"])} kg. Single-reading quotient ρ = M/V = {raw/i*1000:.1f} kg m⁻³. The slope over all observations gives the reported density.'
 if s=='vernier-micrometer':return f'd = {i:.1f} mm = {fmt(r["x"])} m; C = {raw:.2f} mm = {fmt(r["y"])} m. Single-reading ratio π = C/d = {raw/i:.5f}. The slope over all observations gives the reported geometric ratio.'
 if s=='friction-laws':return f'N = {i:.1f} N; Ff = {raw:.2f} N. Single-reading quotient μ = Ff/N = {raw/i:.4f}. Linear regression over all loads yields the reported coefficient of kinetic friction.'
 if s=='principle-of-moments':return f'm = {i:.1f} g = {i/1000:.4f} kg; 1/m = {r["x"]:.4f} kg⁻¹; observed balancing distance d_m = {raw:.1f} cm = {fmt(r["y"])} m. Single-reading ruler mass M = (m × d_m) / d_rule = ({i/1000:.4f} × {fmt(r["y"])}) / 0.150 = {(i/1000)*r["y"]/0.150:.4f} kg. Linear regression over all reciprocal masses yields the reported meter rule mass.'
 if s=='force-table':return f'θ = {i:.1f}°; x = cos({i:.1f}°) = {r["x"]:.5f}; observed equilibrant mass m_E = {raw:.1f} g = {fmt(r["y"])} kg. Single-reading component mass M₀ = m_E / (2 cos θ) = {fmt(r["y"])} / (2 × {r["x"]:.5f}) = {r["y"]/(2*r["x"]):.4f} kg. Linear regression of m_E against cos θ yields the reported applied mass M₀.'
 if s=='equilibrium-forces':return f'x = {i:.2f} m; relative distance x − x_A = {i-0.10:.2f} m; observed reaction R_B = {raw:.2f} N; left reaction R_A = 7.00 − {raw:.2f} = {7.00-raw:.2f} N. Single-station load estimate W = (R_B − 1.00) × 0.800 / ({i-0.10:.2f}) = {(raw-1.00)*0.80/(i-0.10):.3f} N. Linear regression over all load positions yields the reported load weight.'
 if s=='free-fall':return f'Drop height h = {i:.2f} m; observed transit time t = {raw:.4f} s; square of time t² = {r["x"]:.6f} s². Single-station estimate g = 2h / t² = 2 × {i:.2f} / ({raw:.4f})² = {2*i/(raw*raw):.4f} m s⁻². Linear regression of h against t² across all heights yields the reported gravity value.'
 if s=='newtons-second-law':return f'Accelerating force F = {i:.2f} N; observed acceleration a = {raw:.3f} m s⁻². Single-station estimate M_total = F / a = {i:.2f} / {raw:.3f} = {i/raw:.4f} kg. Linear regression of a against F across all force settings yields the reported system mass.'
 if s=='ballistic-pendulum':return f'Pendulum mass M_p = {i:.0f} g = {i/1000:.3f} kg; total mass M = {(i+50)/1000:.3f} kg; 1/M = {r["x"]:.3f} kg⁻¹; rise height h = {raw:.2f} cm; post-collision velocity V = √(2gh) = {r["y"]:.3f} m s⁻¹. Initial momentum p₀ = M · V = {(i+50)/1000*r["y"]:.4f} kg m s⁻¹; muzzle velocity v₀ = p₀ / m_b = {(i+50)/1000*r["y"]/0.050:.3f} m s⁻¹. Linear regression of V against 1/M yields the reported muzzle velocity.'
 if s=='conical-pendulum':return f'Apex angle θ = {i:.1f}°; vertical depth h = L cos θ = {r["x"]:.4f} m; observed time for 20 revs t₂₀ = {raw:.2f} s; period T = {raw/20:.4f} s; T² = {r["y"]:.4f} s². Single-station estimate g = 4π²h / T² = {4*math.pi**2*r["x"]/r["y"]:.4f} m s⁻². Linear regression of T² against h yields the reported acceleration due to gravity.'
 if s=='flywheel-inertia':return f'Applied torque τ = {i:.3f} N m; observed angular acceleration α = {raw:.3f} rad s⁻². Single-station estimate I = τ / α = {i:.3f} / {raw:.3f} = {i/raw:.4f} kg m². Linear regression of α against τ across all torque stations yields the reported moment of inertia.'
 if s=='specific-heat-capacity':return f'Specimen mass m_s = {i:.1f} g = {i/1000:.4f} kg; observed equilibrium temperature T_f = {raw:.2f} °C; heat drop factor m_s(T_s − T_f) = {i/1000:.4f} × (100.0 − {raw:.2f}) = {r["x"]:.4f} kg K; heat absorbed by calorimeter and water Q_sys = 920.92 × ({raw:.2f} − 20.0) = {r["y"]:.2f} J. Single-reading estimate c_s = Q_sys / [m_s(T_s − T_f)] = {r["y"]/r["x"]:.2f} J kg⁻¹ K⁻¹. Linear regression of Q_sys against m_s(T_s − T_f) across all sample masses yields the reported specific heat capacity.'
 if s=='newtons-cooling':return f'Elapsed time t = {i:.1f} min; observed temperature T = {raw:.2f} °C; temperature excess θ = T − T₀ = {raw:.2f} − 20.0 = {raw-20.0:.2f} °C; log ratio y = ln(θ₀ / θ) = ln(60.0 / {raw-20.0:.2f}) = {r["y"]:.4f}. Single-station estimate k = y / t = {r["y"]/i:.4f} min⁻¹. Linear regression of ln(θ₀ / θ) against t across all time intervals yields the reported cooling constant.'
 if s=='solidification-cooling':return f'Salol mass m = {i:.1f} g = {i/1000:.4f} kg; observed plateau duration Δt = {raw:.2f} min; constant heat loss rate R = 270.0 J min⁻¹; latent heat liberated Q_latent = R × Δt = 270.0 × {raw:.2f} = {r["y"]:.1f} J. Single-reading estimate L_f = Q_latent / m = {r["y"]/r["x"]:.1f} J kg⁻¹ = {r["y"]/r["x"]*0.001:.2f} kJ kg⁻¹. Linear regression of Q_latent against m across all charges yields the reported latent heat of fusion.'
 if s=='latent-heat-vaporization':return f'Condensed steam mass m_v = {i:.1f} g = {i/1000:.4f} kg; observed final temperature T_f = {raw:.2f} °C; heat absorbed by calorimeter and water Q_gain = 866.08 × ({raw:.2f} − 15.0) = {866.08*(raw-15.0):.2f} J; sensible heat released by condensed water cooling to T_f: Q_sens = {i/1000:.4f} × 4186 × (100.0 − {raw:.2f}) = {i/1000*4186*(100.0-raw):.2f} J; net latent heat Q_net = Q_gain − Q_sens = {r["y"]:.2f} J. Single-reading estimate L_v = Q_net / m_v = {r["y"]/r["x"]:.1f} J kg⁻¹ = {r["y"]/r["x"]*0.001:.2f} kJ kg⁻¹. Linear regression of Q_net against m_v across all condensation runs yields the reported latent heat of vaporization.'
 if s=='latent-heat-fusion':return f'Dry ice mass m_i = {i:.1f} g = {i/1000:.4f} kg; observed final temperature T_f = {raw:.2f} °C; heat lost by calorimeter and initial warm water Q_lost = 866.08 × (30.00 − {raw:.2f}) = {866.08*(30.0-raw):.2f} J; sensible heat absorbed by meltwater warming from 0 °C to T_f: Q_melt = {i/1000:.4f} × 4186 × {raw:.2f} = {i/1000*4186*raw:.2f} J; net latent heat of fusion Q_net = Q_lost − Q_melt = {r["y"]:.2f} J. Single-reading estimate L_f = Q_net / m_i = {r["y"]/r["x"]:.1f} J kg⁻¹ = {r["y"]/r["x"]*0.001:.2f} kJ kg⁻¹. Linear regression of Q_net against m_i across all ice charges yields the reported latent heat of fusion.'
 if s=='thermal-expansion':return f'Temperature rise ΔT = {i:.1f} °C = {i:.1f} K; original rod length L₀ = 1.000 m; product L₀ΔT = {r["x"]:.1f} m K; observed elongation ΔL = {raw:.3f} mm = {fmt(r["y"])} m. Single-reading estimate α = ΔL / (L₀ΔT) = {fmt(r["y"])} / {r["x"]:.1f} = {r["y"]/r["x"]:.4e} K⁻¹ = {r["y"]/r["x"]*1e6:.2f} × 10⁻⁶ K⁻¹. Linear regression of ΔL against L₀ΔT across all temperature stations yields the reported linear thermal expansion coefficient.'
 if s=='mechanical-equivalent-heat':return f'Revolutions N = {i:.0f} rev; mechanical work done W = 2π × 0.050 m × (3.00 kg × 9.807 m s⁻²) × {i:.0f} = {r["y"]:.2f} J; observed final temperature T_f = {raw:.2f} °C; temperature rise ΔT = {raw:.2f} − 20.00 = {raw-20.0:.2f} °C; heat absorbed Q = 118.48 cal K⁻¹ × {raw-20.0:.2f} K = {r["x"]:.2f} cal. Single-trial estimate J = W / Q = {r["y"]:.2f} / {r["x"]:.2f} = {r["y"]/r["x"]:.3f} J cal⁻¹. Linear regression of W against Q across all revolution settings yields the reported mechanical equivalent of heat.'
 if s=='boyles-law':return f'Confined volume V = {i:.1f} cm³ = {i*1e-6:.6f} m³; reciprocal volume 1/V = {r["x"]:.1f} m⁻³; observed absolute pressure P = {raw:.2f} kPa = {r["y"]:.0f} Pa; single-trial constant k = P · V = {r["y"]:.0f} × ({i*1e-6:.6f}) = {r["y"]*(i*1e-6):.4f} J. Linear regression of P against 1/V across all volume settings yields the reported isothermal state constant.'
 if s=='charles-law-volume':return f'Water bath temperature t = {i:.1f} °C = {i+273.15:.2f} K; observed volume V = {raw:.2f} cm³ = {r["y"]:.8f} m³; thermal volume expansion ΔV = {raw-100.0:.2f} cm³; single-reading estimate β = ΔV / (V₀ · t) = ({raw-100.0:.2f} × 10⁻⁶) / (1.000 × 10⁻⁴ × {max(0.1,i):.1f}) = {(raw-100.0)/(100.0*max(0.1,i)):.6f} K⁻¹. Linear regression of V against t across all temperature stations yields the reported volume expansion coefficient.'
 return f'u = {i:.0f} cm = {i/100:.3f} m; v = {raw:.1f} cm = {raw/100:.3f} m. Thus 1/u = {r["x"]:.6f} m⁻¹ and 1/v = {r["y"]:.6f} m⁻¹. Single-pair f = uv/(u+v) = {(i*raw/(i+raw)):.4f} cm.'

def graph(c,rows,f):
 xs=[r['x']*c['xScale'] for r in rows];ys=[r['y']*c['yScale'] for r in rows];xmin=min(xs);xmax=max(xs);ymin=min(ys);ymax=max(ys);dx=xmax-xmin;dy=ymax-ymin;xmin-=dx*.1;xmax+=dx*.1;ymin-=dy*.1;ymax+=dy*.1
 px=lambda x:65+(x-xmin)/(xmax-xmin)*540;py=lambda y:280-(y-ymin)/(ymax-ymin)*245
 svg=f'<svg viewBox="0 0 650 340" role="img" aria-label="Five simulated observations and a best-fit line for {E(c["shortTitle"])}">'
 for j in range(5):
  x=xmin+j*(xmax-xmin)/4;y=ymin+j*(ymax-ymin)/4
  svg+=f'<line x1="65" y1="{py(y)}" x2="605" y2="{py(y)}" stroke="#dfe6d5"/><text x="53" y="{py(y)+4}" text-anchor="end" fill="#7d8e71" font-size="10">{y:.2f}</text><text x="{px(x)}" y="300" text-anchor="middle" fill="#7d8e71" font-size="10">{x:.2f}</text>'
 line=[]
 for j in range(101):
  x=xmin+j*(xmax-xmin)/100;y=(f['m']*x/c['xScale']+f['b'])*c['yScale']
  if ymin<=y<=ymax:line.append(f'{px(x)},{py(y)}')
 svg+=f'<polyline points="{" ".join(line)}" stroke="#52794a" stroke-width="2" fill="none"/>'
 for r in rows:svg+=f'<circle cx="{px(r["x"]*c["xScale"])}" cy="{py(r["y"]*c["yScale"])}" r="4.5" fill="#b65031"/>'
 return svg+f'<path d="M65 35V280H605" stroke="#9caf8b" fill="none"/><text x="335" y="331" text-anchor="middle" fill="#507043" font-size="11">{E(c["xAxis"])}</text><text transform="translate(14 158) rotate(-90)" text-anchor="middle" fill="#507043" font-size="11">{E(c["yAxis"])}</text></svg>'

def theory(c):
 return '<div class="equation-banner"><small>THE WORKING RELATIONSHIP</small><div style="font-size:26px">'+E(c['fitEquation'])+'</div><p>Keep the physical quantities, graph variables and units consistent.</p></div>'+''.join('<details class="theory-topic"'+(' open' if i==0 else '')+'><summary><span>'+str(i+1).zfill(2)+'</span>'+E(t['title'])+'</summary><div class="theory-content"><p>'+E(t['text'])+'</p><div class="formula">'+E(t['formula'])+'</div><details><summary>'+E(t['question'])+'</summary><p>'+E(t['answer'])+'</p></details></div></details>' for i,t in enumerate(c['topics']))

def method(c):return ''.join('<article class="step"><span class="step-number">'+str(i+1)+'</span><div><h3>'+E(t['title'])+'</h3><p>'+E(t['text'])+'</p><details><summary>Why this step matters</summary><p>'+E(t['why'])+'</p></details></div></article>' for i,t in enumerate(c['procedure']))

def report(c,rows,f,out):
 value,se,reference=estimate(c,f);percent=abs(value-reference)/reference*100
 obs=''.join('<tr><td>'+str(i+1)+'</td><td>'+f'{r["input"]:.{c["inputDecimals"]}f}'+'</td><td>'+f'{r["raw"]:.{c["rawDecimals"]}f}'+'</td><td>'+fmt(r['x'])+'</td><td>'+fmt(r['y'])+'</td><td>'+fmt(f['m']*r['x']+f['b'])+'</td><td>'+fmt(r['y']-(f['m']*r['x']+f['b']))+'</td></tr>' for i,r in enumerate(rows))
 csvio=io.StringIO();writer=csv.writer(csvio);writer.writerow(['dataset','input_'+c['inputUnit'],'observed_'+c['rawUnit'],'x_SI','y_SI','fit_y_SI','residual_y_SI'])
 for r in rows:writer.writerow(['simulated_demo',r['input'],r['raw'],r['x'],r['y'],f['m']*r['x']+f['b'],r['y']-f['m']*r['x']-f['b']])
 csvpath=f'/physics/{c["slug"]}/sample-data.csv';(out/csvpath.lstrip('/')).write_text(csvio.getvalue())
 uncertainty={
 'ohms-law':'Current and voltage calibration, contact resistance, ammeter burden and voltmeter loading affect real measurements. Heating changes the resistance. The inverse-gradient standard error omits calibration and temperature uncertainty. A perfect straight line from an ideal simulator does not imply zero physical uncertainty.',
 'metre-bridge':'The balance-length scale is rounded to 0.1 cm. Contact and end resistances, wire nonuniformity and resistance-box tolerances are omitted. The transform (100−l)/l has nonlinear length uncertainty. A vertical equal-weight fit does not model shared scale errors. Interchange the resistances and repeat in a real lab.',
 'rc-charging':'Source voltage, timebase, voltage calibration, capacitor tolerance, leakage and probe loading contribute uncertainty. Logarithmic transformation amplifies voltage error near the supply voltage. Equal-weight fitting in transformed coordinates is a teaching approximation; consider a direct nonlinear fit and an uncertainty model for real data.',
 'glass-slab':'Microscope focusing, scale calibration, surface parallelism and parallax affect each depth. Real and apparent depth share the R₂ reading, so their errors are correlated. A vertical equal-weight fit ignores this covariance. The model uses paraxial viewing through a plane parallel transparent slab.',
 'diffraction-grating':'Angular resolution, line-density calibration, alignment and normal incidence affect wavelength. Symmetric angle readings reduce a shared zero offset but do not remove all alignment errors. sin(θ) has angle-dependent uncertainty. The slope error excludes uncertainty in grating spacing.',
 'simple-pendulum':'Timing resolution, cycle counting, pivot-to-bob-centre length, amplitude and support motion affect a real result. Since T = t/N, timing twenty cycles reduces the fractional impact of a single endpoint timing error. An omitted finite-amplitude correction biases the inferred g downward. Length errors and correlated timing errors require additional treatment.',
 'bifilar-suspension':'The inferred inertia depends on mass, string length, timing and the square of half-separation a. Independent fractional uncertainties approximately satisfy (uI/I)² = (uM/M)² + (uL/L)² + (2uT/T)² + (2ua/a)² + (ug/g)² for a single reading. Fit uncertainty alone excludes these geometrical and calibration terms.',
 'young-modulus':'Young’s modulus is proportional to L₀ and inversely proportional to the extension/force slope and diameter squared. For independent inputs, (uY/Y)² ≈ (uL/L)² + (2ud/d)² + (um/m)². A shared diameter error affects all readings and is not represented by scatter around the fitted line.',
 'stokes-viscosity':'Viscosity is proportional to density difference and inversely proportional to the v-versus-r² gradient. Radius errors enter r², so horizontal-axis uncertainty matters. A naive equal-weight vertical least-squares fit does not account for it. Gate spacing, timing, liquid temperature and wall/end effects also contribute in a real apparatus.',
 'convex-lens':'Both inverse-distance axes have measurement uncertainty. The equal-weight vertical regression shown here is a teaching calculation, not a full errors-in-variables analysis. Scale zero, lens thickness, alignment and subjective focus affect real distances. f = 1/b gives an intercept-only standard error uf = ub/b² when other effects are ignored.',
 'hookes-law':'Scale alignment, pointer zeroing, weight mass tolerances, and imperfect spring elasticity contribute uncertainty. Real helical springs have an effective dynamic self-mass and initial winding tension. The regression slope error reflects residual scatter but excludes calibration systematic errors. In a physical laboratory, load incrementally and decrementally to verify the absence of elastic hysteresis.',
 'density-measurement':'Volumetric measurement by fluid displacement is subject to meniscus reading uncertainty, liquid adherence to cylinder walls, and thermal expansion. Mass measurements on a mechanical balance involve knife-edge friction and buoyancy in ambient air. The regression slope error accounts for linear scatter, but does not capture shared calibration offsets in the volumetric scale or balance tare.',
 'vernier-micrometer':'Least count resolution (0.02 mm for vernier calipers, 0.01 mm for micrometers), contact pressure variations, specimen surface irregularities, and ribbon bending thickness contribute uncertainty. Measuring ribbon thickness creates an effective diameter d + t, giving a small positive intercept. The slope regression standard error evaluates random scatter, but does not include ribbon thermal expansion or scale calibration errors.',
 'friction-laws':'Local variations in microscopic surface roughness, stick-slip velocity fluctuations, track leveling error, and dynamometer spring calibration contribute uncertainty. Pulling at a slight angle alters the effective normal force. The linear regression standard error reflects scatter in steady-state sliding readings but excludes systematic track misalignment.',
 'principle-of-moments':'Reading resolution of the meter scale (±0.5 mm), knife-edge fulcrum width and bearing friction, alignment of the center of gravity relative to the geometric center (wood grain non-uniformity), and hanger string mass contribute uncertainty. The linear regression standard error quantifies random placement scatter, but does not capture zero tare offsets in the slotted weights or ambient air currents acting on the extended meter rule arm.',
 'force-table':'Angular scale resolution of the circular table (±0.25°), pulley axle bearing friction and string-pulley groove contact resistance, knot stretching and non-coaxial central ring alignment, and slotted mass manufacturing tolerances contribute uncertainty. Tapping the table breaks static friction dead-bands. The regression slope standard error quantifies random ring-centering scatter, but excludes shared systematic zero-degree alignment errors.',
 'equilibrium-forces':'Reading resolution of the tubular dynamometers (±0.01 N), beam leveling angle tilt error causing non-vertical suspension, knife-edge bearing contact offset, and wood moisture mass variation contribute uncertainty. Dynamometer spring zero offsets must be calibrated under vertical tare. The regression slope standard error quantifies random load-position reading scatter, but does not capture shared calibration offsets in dynamometer spring constants.',
 'free-fall':'Chronometer timebase jitter and trigger contact latency (±0.0001 s), millimeter scale parallax and zero-reference indexing error (±0.5 mm), residual electromagnetic core remanence delay, aerodynamic form drag at higher velocities, and ambient room air currents contribute uncertainty. The OLS regression standard error reflects random timing scatter across stations, but does not capture shared scale zero offsets or geographic latitude differences from the 9.80665 m s⁻² standard reference.',
 'newtons-second-law':'Photogate transit timing resolution (±0.0001 s), flag width measurement uncertainty (±0.05 mm), residual rolling friction and air resistance along the track, cord stretching and pulley bearing drag, and the small unmodelled rotational inertia of the pulley wheel (equivalent mass ~0.005 kg) contribute uncertainty. The OLS inverse-slope standard error reflects random timing scatter across force settings, but does not include shared static scale mass calibration errors or slight track inclination zero offsets.',
 'ballistic-pendulum':'Ratchet tooth spacing resolution (±0.5 mm in rise height), friction work dissipated by the ratchet pawl during swing, suspension string mass and rotational inertia of the pendulum arm, air resistance during the swing arc, and imperfectly horizontal firing alignment contribute uncertainty. The OLS regression standard error reflects random scatter across pendulum mass settings, but does not include shared projectile mass balance calibration errors or mechanical spring fatigue in the launcher.',
 'conical-pendulum':'Timing resolution over twenty revolutions (±0.01 s), apex angle determination and floor circle parallax (±0.5°), aerodynamic drag on the cord and spherical bob causing orbital decay, and slight elliptical orbital precession (eccentricity) contribute uncertainty. The OLS inverse-slope standard error reflects random period scatter across angle stations, but does not include shared cord stretch under tension or suspension pivot bearing friction.',
 'flywheel-inertia':'Optical encoder angular quantization (±0.001 rad s⁻²), drum radius caliper measurement uncertainty (±0.05 mm), cord thickness contributing an effective radius r + d_cord/2, bearing friction torque variations during rotation, and the small unmodelled linear inertia of the falling mass (m r² ~0.00008 kg m²) contribute uncertainty. The OLS inverse-slope standard error reflects random timing scatter across torque stations, but does not capture shared static weight calibration errors or non-uniform cord winding layers.',
 'specific-heat-capacity':'Thermometer immersion depth and stem emergent exposure correction, heat lost by radiation and convection during the physical transfer of the hot copper specimen from the steam boiler to the calorimeter vessel (~1–2 s latency), water splashing during immersion, evaporation loss from the warm water surface, non-uniform temperature gradients prior to complete mechanical stirring, and balance mass measurement precision (±0.05 g) contribute experimental uncertainty. The OLS regression standard error reflects random scatter across sample mass settings, but does not capture unmodelled environmental radiation exchanges or systematic calibration offsets in the water equivalent determination.',
 'newtons-cooling':'Ambient water jacket temperature drift (±0.1°C), convection drafts around the wooden lid apertures, thermometer thermal response lag and emergent stem temperature gradient, spatial temperature stratification inside the unagitated cooling water, and evaporation mass loss contribute experimental uncertainty. The OLS regression standard error reflects random scatter across time stations, but does not capture non-linear convective cooling departures at larger initial temperature excesses.',
 'solidification-cooling':'Thermal supercooling before nucleation, non-uniform radial solidification fronts from the glass wall inward, temperature gradients across the partially crystallized solid slush, thermometer stem conduction, ambient draft fluctuations around the test tube mouth, and chemical purity variations in salol contribute experimental uncertainty. The OLS regression standard error reflects random scatter in plateau duration determination, but does not capture unmodelled sensible heat release during transient phase coexistence.',
 'latent-heat-vaporization':'Water droplet carryover (wet steam) passing through the delivery tube despite the steam trap, radiation and convective heat exchanges during the condensation interval (~5–10 min), evaporation loss from the agitated warm water surface, thermometer stem emergent column cooling, atmospheric barometric pressure departure altering steam boiling temperature Ts from 100.0°C (±0.037°C per mmHg), and analytical balance precision in measuring condensed steam mass (±0.01 g) contribute experimental uncertainty. The OLS regression standard error reflects random scatter across condensation charges, but does not capture unmodelled entrained moisture or residual radiation offsets.',
 'latent-heat-fusion':'Surface moisture adhering to ice chips (wet ice) introducing pre-melted water that releases zero latent heat, heat exchange with the ambient environment during ice melting and dissolution (~3–5 min), water splashing during ice addition, thermometer thermal lag and stem emergent column correction, spatial thermal stratification before complete agitation, and balance precision in weighing melting ice chips (±0.02 g) contribute experimental uncertainty. The OLS regression standard error reflects random scatter across sample mass settings, but does not capture unmodelled surface water film or residual convection exchanges.',
 'thermal-expansion':'Micrometer screw gauge zero-point indexing and backlash error (±0.002 mm), electrical contact sensitivity threshold and contact point oxidation, temperature non-uniformity along the longitudinal steam jacket (temperature gradient between steam inlet and outlet), heat conduction loss at the end supports where the rod protrudes, thermal response lag of the enclosed thermometer, and scale uncertainty in measuring initial rod length L0 (±0.5 mm) contribute experimental uncertainty. The OLS regression standard error reflects random scatter across temperature stations, but does not capture shared length measurement offsets or longitudinal thermal gradients.',
 'mechanical-equivalent-heat':'Frictional heat dissipation to the ambient air and support bearings during rotation (~3–8 min), temperature rise non-uniformity across the rotating drum cylinder and internal water, tension fluctuations in the friction belt/cord, spring balance calibration offset, thermometer thermal lag and stem conduction, revolution counter indexing precision (±1 rev), and water evaporation loss contribute experimental uncertainty. The OLS regression standard error reflects random scatter across revolution counts, but does not capture unmodelled convective boundary losses or belt stiffness variations.',
 'boyles-law':'Barometric pressure fluctuations during the observation period (±0.2 mmHg), capillary depression at the mercury-glass menisci in unequal tube diameters (±0.3 mm), room temperature drift affecting isothermal conditions (±0.2°C), non-uniformity in the internal cross-section of the graduated closed tube, parallax errors in reading the mercury columns, and slight trace moisture in the confined air contributing water vapor pressure departures from ideal behavior contribute experimental uncertainty. The OLS regression standard error reflects random reading scatter, but does not capture unmodelled capillary curvature offsets or ambient barometric drift.',
 'charles-law-volume':'Temperature gradients throughout the water heating bath during continuous mechanical stirring (±0.2 °C), thermal response lag of the precision thermometer, capillary stem volume exclusion (a small fraction of the gas column in the capillary remains at intermediate temperature between bath and room air, ~0.8%), meniscus parallax error across the graduated leveling tube (±0.05 cm³), atmospheric barometric fluctuations over the heating cycle (±0.2 mmHg), and slight thermal expansion of the glass bulb envelope (borosilicate glass volume expansion α_v ≈ 10 × 10⁻⁶ K⁻¹) contribute experimental uncertainty. The OLS regression standard error reflects random scatter across temperature stations, but does not capture unmodelled capillary dead-space gradients or glass envelope expansion.'}[c['slug']]
 return f'''<div class="section-top"><div><div class="eyebrow">WORKED EXAMPLE · SIMULATED OBSERVATIONS</div><h2>A complete example report.</h2></div><button class="secondary" onclick="window.print()">Print / save as PDF</button></div><div class="report-notice"><strong>Simulated demonstration data.</strong><p>This report shows the method and arithmetic. It is not evidence of a physical experiment. Replace its observations with your own measurements when preparing a real lab report.</p></div><div class="report-person"><span>Student: __________________</span><span>Student ID: __________________</span><span>Course: __________________</span><span>Date: __________________</span><span>Partner: __________________</span><span>Instructor: __________________</span></div><article class="lab-report"><h3>1. Title and aim</h3><p><strong>{E(c['title'])}.</strong> {E(c['aim'])}</p><h3>2. Abstract</h3><p>Five observations were generated from the ideal teaching model over the settings listed below. A straight-line fit gave an estimate of {E(c['targetName'])} of {fmt(value*c['resultScale'],c['resultDecimals'])} {E(c['resultUnit'])}, differing by {percent:.3f}% from the model value. The reported scatter comes from scale rounding and any stated model approximation, not measured laboratory noise.</p><h3>3. Apparatus and fixed settings</h3><ul>{''.join('<li>'+E(a['name'])+': '+E(a['purpose'])+'</li>' for a in c['apparatus'])}{''.join('<li>'+E(s)+'</li>' for s in c['settings'])}</ul><h3>4. Theory and graph choice</h3><p>{E(c['intro'])}</p><div class="report-equation">{E(c['fitEquation'])}</div><p>The calculation fits y = mx + b in SI units. The graph may display scaled axes for readability; those display factors are removed before calculating the physical result. The gradient has units {E(c['gradientUnit'])}.</p><h3>5. Method</h3><ol>{''.join('<li>'+E(s['text'])+'</li>' for s in c['procedure'])}</ol><h3>6. Observations and calculation table</h3><p>All observations use fixed model settings. Values are rounded only at the instrument reading stage; further calculations use full precision. Repeated physical trials are not claimed.</p><div class="table-card"><table><caption>Table 1. Five simulated measurements; x and y are in SI units.</caption><thead><tr><th>No.</th><th>{E(c['inputLabel'])} ({E(c['inputUnit'])})</th><th>{E(c['rawLabel'])} ({E(c['rawUnit'])})</th><th>x (SI)</th><th>y (SI)</th><th>Fitted y (SI)</th><th>Residual (SI)</th></tr></thead><tbody>{obs}</tbody></table></div><p><a href="{csvpath}" download>Download the sample observations (CSV) ↓</a></p><h3>7. Worked calculation for one observation</h3><div class="report-equation">{E(worked(c,rows[0]))}</div><h3>8. Graph, gradient and final calculation</h3><div class="chart-card">{graph(c,rows,f)}</div><p>Dots show the sample observations. The line is the ordinary least-squares fit.</p><div class="report-equation">x̄ = {fmt(f['mx'])}; ȳ = {fmt(f['my'])}<br>Σ(x − x̄)² = {fmt(f['sxx'])}<br>Σ(x − x̄)(y − ȳ) = {fmt(f['sxy'])}<br>m = Σ(x − x̄)(y − ȳ) / Σ(x − x̄)² = {fmt(f['m'],8)}<br>b = ȳ − mx̄ = {fmt(f['b'],8)}<br>{E(formula(c,f))}</div><h3>9. Uncertainty and comparison</h3><p>Percentage difference = |estimate − model value| / |model value| × 100 = <strong>{percent:.4f}%</strong>. Percentage difference is not experimental uncertainty.</p><p>For n = 5 observations, Σresidual² = {fmt(f['sse'])}; s² = Σresidual²/(n − 2). Gradient standard error = √[s²/Σ(x − x̄)²] = {fmt(f['slopeSE'])}. Intercept standard error = √[s²(1/n + x̄²/Σ(x − x̄)²)] = {fmt(f['interceptSE'])}.</p><p>Propagating only the relevant fit coefficient gives a <strong>fit-only standard error of {fmt(se*c['resultScale'])} {E(c['resultUnit'])}</strong>. This is a one-standard-error quantity under the regression assumptions. Deterministic rounded model data do not supply a complete physical uncertainty budget.</p><p>{E(uncertainty)}</p><h3>10. Result and discussion</h3><div class="report-equation">{E(c['target'])} = {fmt(value*c['resultScale'],c['resultDecimals'])} {E(c['resultUnit'])}<br>Model comparison value: {fmt(reference*c['resultScale'],c['resultDecimals'])} {E(c['resultUnit'])}</div><p>The observations follow the stated model relationship. Check whether the intercept and residual pattern suggest a systematic offset or a missing approximation. Agreement with the model does not independently verify its input constants.</p><h3>11. Precautions and limitations</h3><ul>{''.join('<li>'+E(p)+'</li>' for p in c['precautions'])}</ul><p>{E(c['limitations'])} {E(c['modelExtra'])}</p><h3>12. Conclusion</h3><p>The worked example illustrates how to obtain {E(c['targetName'])} from measurements, graph variables and a fitted coefficient. The estimate is {fmt(value*c['resultScale'],c['resultDecimals'])} {E(c['resultUnit'])}. A real experiment must additionally evaluate the apparatus-specific uncertainties and corrections described above.</p></article>'''


def shell(c,part,body,base,production):
 from build_catalog import head
 path=f'/physics/{c["slug"]}/'+('' if part=='experiment' else part+'/');title=c['shortTitle']+(' Experiment & Simulation' if part=='experiment' else ' Theory & Equations' if part=='theory' else ' Lab Report: Data & Calculations')+' | Open STEM Lab'
 desc={'experiment':c['aim']+' Explore a virtual apparatus, collect readings and analyse a graph.','theory':'Understand '+c['shortTitle'].lower()+': the equations, assumptions, supporting concepts and measurement method.','report':'A worked '+c['shortTitle'].lower()+' lab report with simulated observation tables, graph, calculations, uncertainty and results.'}[part]
 header=head(path,title,desc,base,production).replace('<link rel="stylesheet" href="/catalog.css">','<link rel="stylesheet" href="/style.css"><link rel="stylesheet" href="/physics-lesson.css">')
 home=f'/physics/{c["slug"]}/'
 nav='<aside class="sidebar"><a class="brand" style="font-size:20px" href="/">◉ openstemlab.</a><a class="side-subject" href="/subjects/physics/">← Physics experiments</a><div class="side-label">EXPERIMENT '+str(c['number']).zfill(2)+'</div><nav aria-label="Lesson navigation">'
 for href,label in [(home,'Explore the experiment'),(home+'theory/','Understand the theory'),(home+'#apparatus','Know your apparatus'),(home+'#method','Follow the method'),(home+'#results','Analyse your results'),(home+'#check','Check your understanding'),(home+'report/','Sample lab report')]:nav+='<a class="nav-item'+(' active' if path==href else '')+'" href="'+href+'">'+label+'</a>'
 nav+='<a class="nav-item" href="/experiments/">Search all experiments</a></nav><div class="side-note"><span class="small-sun">✳</span><p>Learn by doing.<br>Understand by exploring.</p></div><a class="text-button" href="/">← All subjects</a></aside>'
 heading=c['title'] if part=='experiment' else c['shortTitle']+' theory' if part=='theory' else c['shortTitle']+' lab report'
 return header+'<body>'+nav+'<main><header class="topbar"><div><a href="/subjects/physics/">Physics</a> / '+E(c['shortTitle'])+'</div><span class="free-label">FREE TO EXPLORE</span></header><section class="page-heading"><div class="eyebrow">EXPERIMENT '+str(c['number']).zfill(2)+' · PHYSICS LABORATORY</div><h1>'+E(heading)+'</h1><p>'+E(desc)+'</p></section><nav class="lab-navigation" aria-label="Experiment pages"><a href="'+home+'">Workbench</a><a href="'+home+'theory/">Detailed theory</a><a href="'+home+'#method">Method</a><a href="'+home+'#results">My results</a><a href="'+home+'report/">Example report</a></nav>'+body+'<footer><span class="footer-brand">openstemlab.</span><a href="/subjects/physics/">All physics experiments</a><span>Ideal teaching model</span></footer></main>'+ ('<script id="labConfig" type="application/json">'+json.dumps(c,ensure_ascii=False).replace('<',chr(92)+'u003c')+'</script><script src="/physics-models.js"></script><script src="/physics-engine.js"></script>' if part=='experiment' else '')+'</body></html>'


def workbench(c):
 angle='<label for="angle">Starting amplitude</label><output id="angleOut">3°</output><input id="angle" type="range" min="1" max="20" step="1" value="3"><p>Use ≤5° and keep amplitude fixed for a measurement series.</p>' if c['angle'] else ''
 screen='<label for="screen">Screen distance v (cm)</label><output id="screenOut">30.0 cm</output><input id="screen" type="range" min="10" max="80" step="0.1" value="30"><p>Arrow keys adjust by 0.1 cm. Find a sharp image before recording.</p>' if c['slug']=='convex-lens' else ''
 balance='<label for="balance">Jockey position l (cm)</label><output id="balanceOut">50.0 cm</output><input id="balance" type="range" min="15" max="85" step="0.1" value="50"><p>Move the jockey to a null. Arrow keys change length by 0.1 cm.</p>' if c['slug']=='metre-bridge' else ''
 return '<section aria-label="Interactive workbench"><div class="section-top"><div><div class="eyebrow">CHANGE · OBSERVE · MEASURE</div><h2>Your virtual workbench.</h2></div><button id="resetApparatus" class="text-button">Reset apparatus</button></div><div class="new-workbench"><div class="new-visual"><div class="visual-top"><span>IDEAL SIMULATION</span><button id="pauseMotion" class="dark-button">Pause motion</button></div><svg id="apparatusDiagram" viewBox="0 0 720 320" role="img" aria-label="Interactive schematic apparatus for '+E(c['shortTitle'])+'"></svg><div class="new-meter"><div><small>'+E(c['rawLabel'].upper())+'</small><strong id="readingValue">—</strong></div><div><small>MEASUREMENT STATUS</small><p id="liveState" style="font-size:11px;margin:7px 0">Ready for a virtual observation.</p></div></div></div><div class="new-controls"><label for="independent">'+E(c['inputLabel'])+'</label><output id="independentOut">'+str(c['initial'])+' '+E(c['inputUnit'])+'</output><input id="independent" type="range" min="'+str(c['min'])+'" max="'+str(c['max'])+'" step="'+str(c['step'])+'" value="'+str(c['initial'])+'"><label for="independentNumber">Set '+E(c['shortInput'])+' ('+E(c['inputUnit'])+')</label><input id="independentNumber" type="number" min="'+str(c['min'])+'" max="'+str(c['max'])+'" step="'+str(c['step'])+'" value="'+str(c['initial'])+'">'+angle+screen+balance+'<div class="lab-control-meta">'+E(c['settings'][0])+'</div><button id="measure" class="primary full">'+E(c['measureLabel'])+'</button><button id="recordReading" class="secondary full" disabled>＋ Record observation</button><p id="trialStatus" class="trial-status" role="status">Adjust the apparatus, then take a reading.</p></div></div><p class="data-notice">'+('Timing is generated from the model; a short on-screen trial represents a longer physical interval. Animation is illustrative.' if c['timed'] else 'Readings are generated by an ideal model. The diagram is schematic and is not to scale.')+'</p><details class="model-note"><summary>Simulation assumptions and limits</summary><p>'+E(c['limitations'])+' '+E(c['modelExtra'])+'</p></details></section><section id="apparatus" class="lab-section"><h2>Know your apparatus.</h2><div class="apparatus-list">'+''.join('<article class="apparatus-item"><h3>'+E(a['name'])+'</h3><p>'+E(a['purpose'])+'</p></article>' for a in c['apparatus'])+'</div></section><section id="method" class="lab-section"><div class="eyebrow">FOLLOW THE METHOD</div><h2>A reason behind every step.</h2><p class="intro">'+E(c['aim'])+' Suggested independent settings: '+', '.join(map(str,c['samples']))+' '+E(c['inputUnit'])+'.</p>'+method(c)+'</section><section id="results" class="lab-section"><div class="section-top"><div><div class="eyebrow">YOUR NOTEBOOK · <span id="notebookCount">0</span> OBSERVATIONS</div><h2>Turn measurements into a result.</h2></div><a class="text-button" href="/physics/'+c['slug']+'/report/">See a complete example report ↗</a></div><div class="lab-result-grid"><div class="chart-card"><svg id="labPlot" viewBox="0 0 650 340" role="img" aria-label="Measured observations and fitted graph"></svg><p>Points are your observations. The fit uses SI x and y values before display scaling.</p></div><div class="fit-card lab-fit"><span class="eyebrow">LINEAR FIT · y = mx + b</span><div id="fitSummary"></div><div class="report-equation">'+E(c['fitEquation'])+'</div></div></div><div class="table-card"><table><thead><tr><th>#</th><th>'+E(c['inputLabel'])+' ('+E(c['inputUnit'])+')</th><th>'+E(c['rawLabel'])+' ('+E(c['rawUnit'])+')</th><th>'+E(c['xAxis'])+'</th><th>'+E(c['yAxis'])+'</th><th>Remove</th></tr></thead><tbody id="readingRows"></tbody></table><p id="emptyReadings">No readings yet. Take a virtual measurement and record it.</p></div><div class="lab-reading-actions"><button id="downloadReadings" class="secondary" disabled>↓ Export CSV</button><button id="clearReadings" class="secondary" disabled>Clear notebook</button></div><div class="source-box"><h3>Calculate it yourself.</h3><label for="studentEstimate">Your estimate of '+E(c['target'])+' ('+E(c['resultUnit'])+')</label> <input id="studentEstimate" type="number" step="any" min="0" style="max-width:140px"><button id="checkEstimate" class="secondary" style="margin-left:10px">Check calculation</button><p id="estimateFeedback" role="status"></p></div></section><section id="check" class="lab-section lab-questions"><div class="eyebrow">CHECK YOUR UNDERSTANDING</div><h2>Explain what the measurements mean.</h2>'+''.join('<article class="quiz-card"><h3>'+E(q['question'])+'</h3><div class="quiz-choices">'+''.join('<button class="quiz-option" data-quiz="'+str(i)+'" data-choice="'+str(j)+'">'+E(a)+'</button>' for j,a in enumerate(q['options']))+'</div><p id="quizFeedback'+str(i)+'" class="quiz-feedback" role="status"></p></article>' for i,q in enumerate(c['quiz']))+'</section>'


def build_physics(out,base,production):
 published=[c for c in specs() if c['published']]
 for name,dest in [('models.js','physics-models.js'),('engine.js','physics-engine.js'),('lesson.css','physics-lesson.css')]: (out/dest).write_text((ROOT/'content/physics'/name).read_text())
 db=sqlite3.connect(ROOT/'data/catalog.sqlite3');sid=db.execute("SELECT id FROM subjects WHERE slug='physics'").fetchone()[0];paths=[]
 for c in published:
  slug=c['slug'];home=f'/physics/{slug}/';(out/home.lstrip('/')).mkdir(parents=True,exist_ok=True);rows=[observation(c,v) for v in c['samples']];f=fit(rows)
  for part,body in [('experiment',workbench(c)),('theory','<section>'+theory(c)+'<div class="insight"><span>↳</span><div><strong>Connect the equations to a measurement.</strong><p>'+E(c['modelExtra'])+'</p></div></div></section>'),('report',report(c,rows,f,out))]:
   path=home+('' if part=='experiment' else part+'/');file=out/path.lstrip('/')/'index.html';file.parent.mkdir(parents=True,exist_ok=True);file.write_text(shell(c,part,body,base,production));paths.append(path)
  db.execute('INSERT INTO experiments(subject_id,slug,title,status,page_path,theory_path,report_path) VALUES(?,?,?,?,?,?,?) ON CONFLICT(slug) DO UPDATE SET title=excluded.title,status=excluded.status,page_path=excluded.page_path,theory_path=excluded.theory_path,report_path=excluded.report_path',(sid,slug,c['shortTitle'],'live',home,home+'theory/',home+'report/'))
 db.commit();db.close();return paths
